// ImportRepository is the resolver for the importRepository field.
func (r *mutationResolver) ImportRepository(ctx context.Context, repoID int, input *models.ImportRepositoryInput) (*ent.Repository, error) {
	// Load Repository
	repo, err := r.client.Repository.Get(ctx, repoID)
	if err != nil {
		return nil, err
	}

	// Configure Filters
	filter := func(string) bool { return true }
	if input != nil && input.IncludeDirs != nil {
		filter = func(path string) bool {
			for _, prefix := range input.IncludeDirs {
				// Ignore Leading /
				path = strings.TrimPrefix(path, "/")
				prefix = strings.TrimPrefix(prefix, "/")

				// Include if matching
				if strings.HasPrefix(path, prefix) {
					return true
				}
			}
			return false
		}
	}

	// Import Tomes
	if err := r.importer.Import(ctx, repo, filter); err != nil {
		return nil, err
	}

	updated, err := repo.Update().SetLastImportedAt(time.Now()).Save(ctx)
	if err != nil {
		return nil, err
	}
	logging.Audit(auditCtx(ctx), "host", "repository.imported", "repository imported",
		"repository_id", updated.ID,
		"repository_url", updated.URL,
	)
	return updated, nil
}

// ResetUserAPIKey is the resolver for the resetUserAPIKey field.
func (r *mutationResolver) ResetUserAPIKey(ctx context.Context) (*ent.User, error) {
	authUser := auth.UserFromContext(ctx)
	if authUser == nil {
		return nil, fmt.Errorf("unauthenticated")
	}

	buf := make([]byte, 64)
	if _, err := io.ReadFull(rand.Reader, buf); err != nil {
		return nil, fmt.Errorf("failed to generate new token: %w", err)
	}
	newToken := base64.StdEncoding.EncodeToString(buf)

	u, err := r.client.User.UpdateOneID(authUser.ID).SetAccessToken(newToken).Save(ctx)
	if err != nil {
		return nil, err
	}
	logging.Audit(auditCtx(ctx), "auth", "user.api_key_reset", "user API key reset",
		"target_user_id", u.ID,
		"target_user_name", u.Name,
	)
	return u, nil
}

