// ClosePortal is the resolver for the closePortal field.
func (r *mutationResolver) ClosePortal(ctx context.Context, portalID int) (*ent.Portal, error) {
	if r.portalMux == nil {
		return nil, fmt.Errorf("portal mux is not configured")
	}

	p, err := r.client.Portal.Get(ctx, portalID)
	if err != nil {
		return nil, fmt.Errorf("failed to fetch portal: %w", err)
	}

	if !p.ClosedAt.IsZero() {
		return nil, fmt.Errorf("portal %d is already closed", portalID)
	}

	actx := auditCtx(ctx)
	var beaconID, hostID int
	if b, bErr := p.QueryBeacon().WithHost().Only(ctx); bErr == nil {
		beaconID = b.ID
		if b.Edges.Host != nil {
			hostID = b.Edges.Host.ID
		}
	} else {
		mutationLog.WarnContext(actx, "failed to query beacon for portal close", "portal_id", portalID, "error", bErr)
	}

	// Publish CLOSE message with an empty stream ID to the portal's input topic
	// so the agent receives it and tears down the portal connections.
	err = r.portalMux.Publish(ctx, r.portalMux.TopicIn(portalID), &portalpb.Mote{
		StreamId: "",
		Payload: &portalpb.Mote_Bytes{
			Bytes: &portalpb.BytesPayload{
				Kind: portalpb.BytesPayloadKind_BYTES_PAYLOAD_KIND_CLOSE,
			},
		},
	})
	if err != nil {
		logging.AuditFailure(actx, "portal", "portal.close_requested", "failed to publish close message to portal",
			append(logging.PortalAttrs(p.ID, beaconID, hostID), "error", err.Error())...,
		)
		return nil, fmt.Errorf("failed to publish close message to portal: %w", err)
	}

	logging.Audit(actx, "portal", "portal.close_requested", "portal close requested", logging.PortalAttrs(p.ID, beaconID, hostID)...)
	return p, nil
}

// ClosePivot is the resolver for the closePivot field.
func (r *mutationResolver) ClosePivot(ctx context.Context, pivotID int) (*ent.ShellPivot, error) {
	pivot, err := r.client.ShellPivot.Query().
		Where(shellpivot.ID(pivotID)).
		WithPortal().
		Only(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to fetch shell pivot: %w", err)
	}

	if !pivot.ClosedAt.IsZero() {
		r.closeCachedPivotSession(ctx, pivot)
		return pivot, nil
	}

	actx := auditCtx(ctx)
	mutationLog.InfoContext(actx, "pivot close requested",
		"pivot_id", pivotID,
		"kind", pivot.Kind,
		"stream_id", pivot.StreamID,
	)

	r.publishPivotCloseMote(actx, pivot)
	r.closeCachedPivotSession(actx, pivot)

	updated, err := r.client.ShellPivot.Get(ctx, pivotID)
	if err != nil {
		return nil, fmt.Errorf("failed to reload shell pivot: %w", err)
	}
	if !updated.ClosedAt.IsZero() {
		return updated, nil
	}

	saved, err := r.client.ShellPivot.UpdateOneID(pivotID).
		SetClosedAt(time.Now()).
		Save(ctx)
	if err != nil {
		return nil, err
	}
	auditAttrs := []any{
		"pivot_id", pivotID,
		"kind", string(pivot.Kind),
		"stream_id", pivot.StreamID,
	}
	if pivot.Edges.Portal != nil {
		auditAttrs = append(auditAttrs, "portal_id", pivot.Edges.Portal.ID)
	}
	logging.Audit(actx, "portal", "portal.pivot_closed", "pivot closed", auditAttrs...)
	return saved, nil
}

